#!/usr/bin/env python3
"""Remove executable JavaScript from an HTML file in place."""
import html
import re
import sys
from pathlib import Path
from bs4 import BeautifulSoup, Comment, Doctype, NavigableString, Tag

URL_ATTRS = frozenset('href src action formaction xlink:href data poster background cite manifest codebase archive longdesc usemap profile'.split())
BAD_CSS = re.compile(r'expression\s*\(|behavior\s*:|-moz-binding\s*:|@import\b|url\s*\(\s*[\"\']?\s*(?:javascript|vbscript|data\s*:\s*text/html)\s*:', re.I)

def unsafe_url(value):
    import urllib.parse
    value = html.unescape(str(value))
    for _ in range(3):
        decoded = urllib.parse.unquote(value)
        if decoded == value:
            break
        value = decoded
    compact = re.sub(r'[\x00-\x20\x7f]+', '', value).casefold()
    if compact.startswith(('javascript:', 'vbscript:', 'data:text/html')):
        return True
    return compact.startswith('data:') and not compact.startswith(('data:image/', 'data:audio/', 'data:video/', 'data:font/'))

def clean_tree(soup):
    for node in list(soup.find_all(['script', 'applet', 'object', 'embed'])):
        node.decompose()
    for tag in soup.find_all(True):
        for attr in list(tag.attrs):
            key = attr.lower()
            value = tag.attrs[attr]
            if key.startswith('on') or key == 'srcdoc':
                del tag.attrs[attr]
            elif key in URL_ATTRS and value is not None and unsafe_url(' '.join(value) if isinstance(value, list) else value):
                del tag.attrs[attr]
            elif key == 'style' and value is not None:
                cleaned = BAD_CSS.sub('', str(value))
                if cleaned:
                    tag.attrs[attr] = cleaned
                else:
                    del tag.attrs[attr]
    return soup

def sanitize(source):
    # html.parser preserves entity spelling and avoids injecting a document wrapper.
    soup = BeautifulSoup(source, 'html.parser')
    clean_tree(soup)
    return str(soup)

def main():
    if len(sys.argv) < 2:
        print('Usage: filter.py HTML_FILE', file=sys.stderr)
        return 2
    path = Path(sys.argv[1])
    with path.open(encoding='utf-8', errors='surrogateescape', newline='') as f:
        source = f.read()
    with path.open('w', encoding='utf-8', errors='surrogateescape', newline='') as f:
        f.write(sanitize(source))
    return 0

if __name__ == '__main__':
    sys.exit(main())
